begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
insert into auth.users(id,aud,role,email,encrypted_password,email_confirmed_at,created_at,updated_at,raw_app_meta_data,raw_user_meta_data)values('00000000-0000-4000-8000-000000191651','authenticated','authenticated','s191-series-a@veyocast.test','test',now(),now(),now(),'{}','{}'),('00000000-0000-4000-8000-000000191652','authenticated','authenticated','s191-series-b@veyocast.test','test',now(),now(),now(),'{}','{}');
insert into public.profiles(id,display_name)values('00000000-0000-4000-8000-000000191651','Series owner A'),('00000000-0000-4000-8000-000000191652','Series owner B');
insert into public.tenants(id,name,slug)values('10000000-0000-4000-8000-000000191651','Series tenant A','s191-series-a'),('10000000-0000-4000-8000-000000191652','Series tenant B','s191-series-b');
insert into public.tenant_settings(tenant_id)values('10000000-0000-4000-8000-000000191651'),('10000000-0000-4000-8000-000000191652');
insert into public.tenant_memberships(tenant_id,user_id,role)values('10000000-0000-4000-8000-000000191651','00000000-0000-4000-8000-000000191651','tenant_owner'),('10000000-0000-4000-8000-000000191652','00000000-0000-4000-8000-000000191652','tenant_owner');
create temporary table sites_fixtures(name text primary key,value jsonb);
insert into sites_fixtures values('document','{"schemaVersion":1,"artboard":{"width":1920,"height":1080,"orientation":"landscape","background":{"kind":"solid","color":"#FAFAF7"},"safeArea":{"top":64,"right":64,"bottom":64,"left":64}},"motion":{"enabled":false,"durationMs":15000,"fps":30},"elements":[],"metadata":{"fontRegistryVersion":"2026-07-24.1","tenantBrandApplied":false},"sitesPresentation":{"kind":"studio","schemaVersion":1,"rendererVersion":"sites-v11","sourceRevision":"b1cae899af19fc39908217253094c5240d7359fc","slide":{"id":"s191-fixture","name":"Typed club update","title":"Onze club","time":"","subtitle":"","location":"","duration":15,"color":"#03438a","background":"#052a55","bold":true,"italic":false,"align":"left","size":58,"context":true,"showLocation":true,"animation":"Geen","transition":"Rustig","orientation":"landscape","themeId":"onzetrots-tv","tv":{"kind":"programma","title":"Onze club","rows":[{"id":"fixture-match","primary":"Team A","home":"Team A","away":"Team B","time":"14:00"}],"scale":100}}}}'::jsonb),('configuration','{"schemaVersion":1,"rendererVersion":"sites-v11","sourceRevision":"b1cae899af19fc39908217253094c5240d7359fc","themeId":"onzetrots-tv","orientation":"landscape","provider":"sportlink","title":"Stand","subtitle":"","overlay":25,"accent":"#03438a","layout":"full","scale":100,"align":"left","safeArea":4,"seconds":15,"rowsPerPage":8,"ledTheme":"blue","ledMoment":"live","ledSide":"unknown","titleScale":100,"scoreScale":100,"logoScale":100,"teamScale":100,"showBranding":true,"showSceneLabel":true,"showClock":true,"showTimeline":true,"timelineLimit":3,"backgroundFit":"contain","grunge":55,"animation":"rise"}'::jsonb);
grant select on sites_fixtures to authenticated;
create temporary table series_results(name text primary key,value jsonb);grant all on series_results to authenticated;
insert into public.studio_series(id,tenant_id,owner_user_id,name)values('30000000-0000-4000-8000-000000191652','10000000-0000-4000-8000-000000191652','00000000-0000-4000-8000-000000191652','Other tenant series');
create function pg_temp.series_inputs(p_conflict boolean default false)returns jsonb language sql as $$select jsonb_agg(jsonb_build_object('projectId',item.project_id,'expectedDraftRevision',case when p_conflict and item.sort_order=1 then 999 else draft.draft_revision end,'document',draft.document_json,'referencedAssetIds','[]'::jsonb,'commandKey',case when item.sort_order=0 then '40000000-0000-4000-8000-000000191655'else '40000000-0000-4000-8000-000000191656'end)order by item.sort_order)from public.studio_series_items item join public.studio_project_drafts draft on draft.tenant_id=item.tenant_id and draft.project_id=item.project_id where item.series_id=((select value from series_results where name='create')->>'seriesId')::uuid$$;
set local role authenticated;select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000191651',true);

select lives_ok($$insert into series_results values('create',public.create_studio_series_v1('10000000-0000-4000-8000-000000191651','Ordered Studio series','[{"name":"First source slide","document":{"schemaVersion":1,"artboard":{"width":1920,"height":1080,"orientation":"landscape","background":{"kind":"solid","color":"#FAFAF7"},"safeArea":{"top":64,"right":64,"bottom":64,"left":64}},"motion":{"enabled":false,"durationMs":15000,"fps":30},"elements":[],"metadata":{"fontRegistryVersion":"2026-07-24.1","tenantBrandApplied":false},"sitesPresentation":{"kind":"studio","schemaVersion":1,"rendererVersion":"sites-v11","sourceRevision":"b1cae899af19fc39908217253094c5240d7359fc","slide":{"id":"s191-fixture","name":"Typed club update","title":"Onze club","time":"","subtitle":"","location":"","duration":15,"color":"#03438a","background":"#052a55","bold":true,"italic":false,"align":"left","size":58,"context":true,"showLocation":true,"animation":"Geen","transition":"Rustig","orientation":"landscape","themeId":"onzetrots-tv","tv":{"kind":"programma","title":"Onze club","rows":[{"id":"fixture-match","primary":"Team A","home":"Team A","away":"Team B","time":"14:00"}],"scale":100}}}},"referencedAssetIds":[],"commandKey":"40000000-0000-4000-8000-000000191651"},{"name":"Second source slide","document":{"schemaVersion":1,"artboard":{"width":1920,"height":1080,"orientation":"landscape","background":{"kind":"solid","color":"#FAFAF7"},"safeArea":{"top":64,"right":64,"bottom":64,"left":64}},"motion":{"enabled":false,"durationMs":15000,"fps":30},"elements":[],"metadata":{"fontRegistryVersion":"2026-07-24.1","tenantBrandApplied":false},"sitesPresentation":{"kind":"studio","schemaVersion":1,"rendererVersion":"sites-v11","sourceRevision":"b1cae899af19fc39908217253094c5240d7359fc","slide":{"id":"s191-fixture","name":"Typed club update","title":"Onze club","time":"","subtitle":"","location":"","duration":15,"color":"#03438a","background":"#052a55","bold":true,"italic":false,"align":"left","size":58,"context":true,"showLocation":true,"animation":"Geen","transition":"Rustig","orientation":"landscape","themeId":"onzetrots-tv","tv":{"kind":"programma","title":"Onze club","rows":[{"id":"fixture-match","primary":"Team A","home":"Team A","away":"Team B","time":"14:00"}],"scale":100}}}},"referencedAssetIds":[],"commandKey":"40000000-0000-4000-8000-000000191652"}]'::jsonb,'40000000-0000-4000-8000-000000191653'))$$,'create all slides and ordered series in one transaction');
select is((select count(*)from public.studio_series_items where tenant_id='10000000-0000-4000-8000-000000191651'),2::bigint,'both slides belong to saved series');
select is((public.create_studio_series_v1('10000000-0000-4000-8000-000000191651','Ordered Studio series','[{"name":"First source slide","document":{"schemaVersion":1,"artboard":{"width":1920,"height":1080,"orientation":"landscape","background":{"kind":"solid","color":"#FAFAF7"},"safeArea":{"top":64,"right":64,"bottom":64,"left":64}},"motion":{"enabled":false,"durationMs":15000,"fps":30},"elements":[],"metadata":{"fontRegistryVersion":"2026-07-24.1","tenantBrandApplied":false},"sitesPresentation":{"kind":"studio","schemaVersion":1,"rendererVersion":"sites-v11","sourceRevision":"b1cae899af19fc39908217253094c5240d7359fc","slide":{"id":"s191-fixture","name":"Typed club update","title":"Onze club","time":"","subtitle":"","location":"","duration":15,"color":"#03438a","background":"#052a55","bold":true,"italic":false,"align":"left","size":58,"context":true,"showLocation":true,"animation":"Geen","transition":"Rustig","orientation":"landscape","themeId":"onzetrots-tv","tv":{"kind":"programma","title":"Onze club","rows":[{"id":"fixture-match","primary":"Team A","home":"Team A","away":"Team B","time":"14:00"}],"scale":100}}}},"referencedAssetIds":[],"commandKey":"40000000-0000-4000-8000-000000191651"},{"name":"Second source slide","document":{"schemaVersion":1,"artboard":{"width":1920,"height":1080,"orientation":"landscape","background":{"kind":"solid","color":"#FAFAF7"},"safeArea":{"top":64,"right":64,"bottom":64,"left":64}},"motion":{"enabled":false,"durationMs":15000,"fps":30},"elements":[],"metadata":{"fontRegistryVersion":"2026-07-24.1","tenantBrandApplied":false},"sitesPresentation":{"kind":"studio","schemaVersion":1,"rendererVersion":"sites-v11","sourceRevision":"b1cae899af19fc39908217253094c5240d7359fc","slide":{"id":"s191-fixture","name":"Typed club update","title":"Onze club","time":"","subtitle":"","location":"","duration":15,"color":"#03438a","background":"#052a55","bold":true,"italic":false,"align":"left","size":58,"context":true,"showLocation":true,"animation":"Geen","transition":"Rustig","orientation":"landscape","themeId":"onzetrots-tv","tv":{"kind":"programma","title":"Onze club","rows":[{"id":"fixture-match","primary":"Team A","home":"Team A","away":"Team B","time":"14:00"}],"scale":100}}}},"referencedAssetIds":[],"commandKey":"40000000-0000-4000-8000-000000191652"}]'::jsonb,'40000000-0000-4000-8000-000000191653')->>'seriesId'),(select value->>'seriesId'from series_results where name='create'),'same idempotency command returns original series');
select is((select count(*)from public.studio_projects where tenant_id='10000000-0000-4000-8000-000000191651'),2::bigint,'replay does not create duplicate projects');
select is((select count(*)from public.studio_series where tenant_id='10000000-0000-4000-8000-000000191652'),0::bigint,'tenant A cannot read tenant B series');
select throws_ok($$insert into public.studio_series(tenant_id,name)values('10000000-0000-4000-8000-000000191651','Direct browser write')$$,'42501','permission denied for table studio_series','direct browser writes remain denied');
select throws_ok($$select public.save_studio_series_v1('30000000-0000-4000-8000-000000191652',1,'[]','40000000-0000-4000-8000-000000191654')$$,'42501','actor cannot edit Studio series','cross-tenant command rejected');
select throws_ok($$select public.save_studio_series_v1(((select value from series_results where name='create')->>'seriesId')::uuid,1,pg_temp.series_inputs(true),'40000000-0000-4000-8000-000000191657')$$,'40001','Studio series draft revision conflict; all changes rolled back','one stale slide rolls back every draft update');
select is((select max(draft_revision)from public.studio_project_drafts where tenant_id='10000000-0000-4000-8000-000000191651'),0::bigint,'preceding slide update was rolled back');
select is((select revision from public.studio_series where tenant_id='10000000-0000-4000-8000-000000191651'),1::bigint,'failed multi-slide save does not advance series');
select lives_ok($$insert into series_results values('save',public.save_studio_series_v1(((select value from series_results where name='create')->>'seriesId')::uuid,1,pg_temp.series_inputs(false),'40000000-0000-4000-8000-000000191658'))$$,'current drafts save together');
select is((select min(draft_revision)from public.studio_project_drafts where tenant_id='10000000-0000-4000-8000-000000191651'),1::bigint,'every draft advances exactly once');
select is((select revision from public.studio_series where tenant_id='10000000-0000-4000-8000-000000191651'),2::bigint,'one atomic series revision is stored');
select is(public.save_studio_series_v1(((select value from series_results where name='create')->>'seriesId')::uuid,1,pg_temp.series_inputs(false),'40000000-0000-4000-8000-000000191659')->>'outcome','conflict','stale series CAS returns conflict without mutation');
select *from finish();rollback;
